import { useEffect, useMemo, useState } from "react";

const SECTION_TABS = {
  account: ["Perfil", "Privacidade", "Plano"],
  map: ["Aparencia", "Idioma & unidades", "Notificacoes"],
  data: ["Exportar"],
};

export default function SettingsModal({ isOpen, onClose }) {
  const [shouldRender, setShouldRender] = useState(isOpen);
  const [activeSection, setActiveSection] = useState("map");
  const [activeTab, setActiveTab] = useState("Aparencia");

  useEffect(() => {
    if (isOpen) {
      setShouldRender(true);
    } else {
      const timeout = setTimeout(() => setShouldRender(false), 220);
      return () => clearTimeout(timeout);
    }
    return undefined;
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return undefined;

    const onEscape = (event) => {
      if (event.key === "Escape") onClose();
    };

    window.addEventListener("keydown", onEscape);
    return () => window.removeEventListener("keydown", onEscape);
  }, [isOpen, onClose]);

  const sectionTabs = useMemo(
    () => SECTION_TABS[activeSection] || [],
    [activeSection],
  );

  if (!shouldRender) return null;

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 100,
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-start",
        padding: "54px 24px 24px 280px",
        background: isOpen ? "rgba(8, 12, 28, 0.62)" : "rgba(8, 12, 28, 0)",
        backdropFilter: "blur(3px)",
        WebkitBackdropFilter: "blur(3px)",
        opacity: isOpen ? 1 : 0,
        pointerEvents: isOpen ? "auto" : "none",
        transition: "opacity 220ms ease-out, background 220ms ease-out",
      }}
    >
      <div
        className="modal"
        onClick={(event) => event.stopPropagation()}
        style={{
          width: "min(624px, calc(100vw - 360px))",
          minHeight: 502,
          maxWidth: 920,
          margin: "8px auto 0",
          background: "linear-gradient(180deg, var(--bg-2), var(--bg-1))",
          border: "1px solid var(--line)",
          borderRadius: 16,
          boxShadow:
            "0 28px 60px -32px rgba(5, 8, 22, 0.95), inset 0 1px 0 rgba(255,255,255,0.06)",
          transform: isOpen ? "translateY(0) scale(1)" : "translateY(16px) scale(0.985)",
          opacity: isOpen ? 1 : 0,
          transition:
            "transform 260ms cubic-bezier(0.22, 1, 0.36, 1), opacity 220ms ease-out",
          overflow: "hidden",
        }}
      >
        <div style={{ padding: "18px 20px 0" }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: 16,
            }}
          >
            <strong style={{ fontSize: 16, letterSpacing: "0.01em" }}>Configuracoes</strong>
            <button
              type="button"
              onClick={onClose}
              style={{
                border: "1px solid var(--line)",
                background: "transparent",
                color: "var(--ink-2)",
                borderRadius: 10,
                width: 34,
                height: 34,
                cursor: "pointer",
              }}
            >
              <span className="material-symbols-outlined" style={{ fontSize: 18 }}>
                close
              </span>
            </button>
          </div>

          <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
            {[
              { id: "account", label: "ACCOUNT" },
              { id: "map", label: "MAP" },
              { id: "data", label: "DATA" },
            ].map((section) => (
              <button
                key={section.id}
                type="button"
                onClick={() => {
                  setActiveSection(section.id);
                  setActiveTab(SECTION_TABS[section.id][0]);
                }}
                style={{
                  border: "1px solid",
                  borderColor: activeSection === section.id ? "var(--coral)" : "var(--line)",
                  color: activeSection === section.id ? "var(--ink)" : "var(--ink-2)",
                  background:
                    activeSection === section.id
                      ? "linear-gradient(180deg, rgba(255,107,94,0.22), rgba(255,107,94,0.12))"
                      : "rgba(255,255,255,0.02)",
                  borderRadius: 999,
                  padding: "8px 14px",
                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: "0.09em",
                  cursor: "pointer",
                  textTransform: "uppercase",
                }}
              >
                {section.label}
              </button>
            ))}
          </div>

          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 18 }}>
            {sectionTabs.map((tab) => (
              <button
                key={tab}
                type="button"
                onClick={() => setActiveTab(tab)}
                style={{
                  border: "1px solid var(--line)",
                  borderRadius: 10,
                  padding: "7px 12px",
                  background: activeTab === tab ? "var(--bg-4)" : "transparent",
                  color: activeTab === tab ? "var(--ink)" : "var(--ink-2)",
                  fontSize: 13,
                  cursor: "pointer",
                }}
              >
                {tab}
              </button>
            ))}
          </div>
        </div>

        <div
          style={{
            borderTop: "1px solid var(--line-soft)",
            padding: "20px 20px 24px",
            display: "grid",
            gap: 14,
          }}
        >
          <div>
            <h3 style={{ margin: 0, fontSize: 18 }}>Aparencia do mapa</h3>
            <p style={{ margin: "8px 0 0", color: "var(--ink-2)", maxWidth: 460, lineHeight: 1.45 }}>
              Ajuste o estilo de tiles, marcadores e elementos da interface.
            </p>
          </div>

          <div style={{ display: "grid", gap: 10 }}>
            <label style={{ fontSize: 13, color: "var(--ink-2)" }}>
              Tema do mapa
              <select
                defaultValue="Satellite"
                style={{
                  marginTop: 6,
                  width: "100%",
                  border: "1px solid var(--line)",
                  borderRadius: 10,
                  background: "var(--bg-3)",
                  color: "var(--ink)",
                  padding: "10px 12px",
                }}
              >
                <option>Satellite</option>
                <option>Terrain</option>
                <option>Dark</option>
              </select>
            </label>

            <label style={{ fontSize: 13, color: "var(--ink-2)" }}>
              Tamanho dos marcadores
              <input
                type="range"
                min="1"
                max="3"
                defaultValue="2"
                style={{ width: "100%", marginTop: 8, accentColor: "var(--coral)" }}
              />
            </label>
          </div>
        </div>
      </div>
    </div>
  );
}
